def scan_records(ctx: Ctx) -> list[dict]:
    recs = []
    if ctx.records.exists():
        for p in sorted(ctx.records.rglob("*.yaml")):
            try:
                d = load_file(p)
                d["_rel"] = str(p.relative_to(ctx.records)).replace("\\", "/")
                recs.append(d)
            except Exception:
                pass
    return recs


def filled_stats(rec: dict) -> tuple[int, int]:
    """(заполнено, осталось TODO) по rules/catalog/candidates одного файла."""
    filled = todo = 0
    for r in rec.get("rules", []) or []:
        if is_todo(r.get("behavior")):
            todo += 1
        else:
            filled += 1
    for r in rec.get("catalog", []) or []:
        if is_todo(r.get("own_name")) or is_todo(r.get("behavior", "")):
            todo += 1
        else:
            filled += 1
    todo += len(rec.get("candidates", []) or [])
    return filled, todo


def step_agents(ctx: Ctx):
    recs = scan_records(ctx)
    authored = [r for r in recs if r.get("status") in ("draft", "reviewed") and not (r.get("meta") or {}).get("auto")]
    sk = [r for r in recs if r.get("status") == "skeleton"]
    todo = sum(filled_stats(r)[1] for r in sk)
    if authored:
        note = f"записей от агентов: {len(authored)} файлов; скелетов осталось {len(sk)} (TODO {todo})"
        state = "ok"
    else:
        note = f"ЖДЁМ АГЕНТОВ: {len(sk)} скелетов в {ctx.records} (см. pipeline/AGENT_PLAYBOOK.md), затем перезапусти run_game"
        state = "waiting"
    ctx.st["steps"]["agents"] = {"state": state, "note": note, "ts": time.strftime("%Y-%m-%d %H:%M:%S")}
    ctx.save()
    log(f"[agents] {state}: {note}")
    return ctx.st["steps"]["agents"]


